type EnvProjectId = keyof typeof SECRET_SPECS;

async function resolveContainerEnvVars(
  projectId: EnvProjectId,
  env: Env,
): Promise<Record<string, string>> {
  const specs = SECRET_SPECS[projectId];
  const envVars: Record<string, string> = { ...(STATIC_ENV_SPECS[projectId as keyof typeof STATIC_ENV_SPECS] ?? {}) };
  const missing: string[] = [];

  for (const { containerKey, binding } of specs) {
    const storeBinding = env[binding as keyof Env] as SecretsStoreSecret | undefined;
    if (storeBinding == null) {
      missing.push(`${binding} (binding not configured)`);
      continue;
    }
    let value: string;
    try {
      value = await storeBinding.get();
    } catch (err) {
      const detail = err instanceof Error ? err.message : String(err);
      missing.push(`${binding} (get() failed: ${detail})`);
      continue;
    }
    if (value === "") {
      missing.push(`${binding} (empty value in Secrets Store)`);
      continue;
    }
    envVars[containerKey] = value;
  }

  if (missing.length > 0) {
    throw new MissingSecretsError(projectId, missing);
  }
  return envVars;
}

async function ensureContainerSecrets(
  projectId: EnvProjectId,
  container: Container<Env>,
  env: Env,
): Promise<void> {
  container.envVars = await resolveContainerEnvVars(projectId, env);
}

function secretsErrorResponse(projectId: string, err: unknown): Response {
  const message =
    err instanceof MissingSecretsError
      ? err.message
      : `FATAL: Failed to load Secrets Store secrets for ${projectId}: ${
          err instanceof Error ? err.message : String(err)
        }`;
  console.error(message, err);
  return new Response(message, {
    status: 503,
    headers: { "Content-Type": "text/plain; charset=utf-8" },
  });
}

