type ContainerBindingKey = (typeof HOSTNAME_TO_BINDING)[keyof typeof HOSTNAME_TO_BINDING];

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const hostname = url.hostname.toLowerCase();
    const bindingKey = HOSTNAME_TO_BINDING[hostname];

    if (!bindingKey) {
      return new Response(
        `No container configured for hostname: ${hostname}`,
        { status: 404 },
      );
    }

    const ns = env[bindingKey as ContainerBindingKey];
    const instance = getContainer(ns as DurableObjectNamespace<Container<Env>>, hostname);
    return instance.fetch(request);
  },
} satisfies ExportedHandler<Env>;
